 # Parse five sequential no-op repeats per policy. Empty-body happy path only.
 groups={}
 for line in a.overhead.read_text().splitlines():
  if not line.startswith('BenchmarkSuccessfulHandler/'):continue
  parts=line.split();mode=parts[0].split('/')[1].rsplit('-',1)[0];groups.setdefault(mode,[]).append({'ns':float(parts[2]),'bytes':int(parts[4]),'allocs':int(parts[6])})
 assert len(groups)==7 and all(len(v)==5 for v in groups.values())
 summary['overhead']=[{'mode':k,'ns':statistics.median(v['ns'] for v in vs),'min_ns':min(v['ns'] for v in vs),'max_ns':max(v['ns'] for v in vs),'bytes':statistics.median(v['bytes'] for v in vs),'allocs':statistics.median(v['allocs'] for v in vs)} for k,vs in groups.items()]
