 provenance={'release':'v0.11.0','source_sha256':summary['source_sha256'],'gzip_sha256':summary['gzip_sha256'],'overhead_sha256':summary['overhead_sha256'],'criteria':d['criteria'],'scope_analysis':d['scope_analysis'],'methodology':d['methodology'],'aggregation':'Each throughput and successful p95 is the median of three run-level values. Whiskers show min/max repeats, not confidence intervals. Rejection, server error and deadline percentages pool counts. Both priorities use100ms whole-schedule useful-work budget. Successful p95 excludes refusals/errors. Queue p95 includes successful immediate admissions with zero wait. Pool waits are real database/sql deltas shared by all priorities of a service; never attributable to one priority. All-service pool waits sum3services. Recovery is end of first whole1s bin meeting90% timely/offered critical work and retaining it through3s recovery; null if not attained in all repeats. Proxy adds a hop; rate/direct do not cap active work. The original protocol verdict and all backend-bound failures remain in scope_analysis. Post-hoc lifetime classification distinguishes proxy admission from canceled remote work. Measurement validation is not all-original-criteria-pass evidence or an advantage claim.','chart_source':'tools/export_comparison.py','harness':'examples/commerce/comparison_recorded.py (byte-identical measured collection protocol); comparison_benchmark.py adds explicit post-hoc analysis. The default comparison_protocol.py changes hardware metadata portability only, not workload or collection logic.','overhead':'commerce-backend/tests/baseline/baseline_test.go, BenchmarkSuccessfulHandler; sequential no-op, observer present in all cases, pre-created request/writer, empty body, no network/SQL/contention/actual queue waiting. Rate1e15 avoids refusals. Adaptive stable profile. Enabled queue tests immediate admission only.'}
 (ROOT/'public/data/comparison-provenance.json').write_text(json.dumps(provenance,indent=2)+'\n')
 import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt
 plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'text.color':'#dae8df','axes.labelcolor':'#bccfc2','xtick.color':'#a9bfb0','ytick.color':'#cbdcd1','axes.edgecolor':'#45604f','figure.facecolor':'#101b16','axes.facecolor':'#101b16','savefig.facecolor':'#101b16'})
 cases=[c['id'] for c in d['methodology']['cases']];colors=['#829d8e' if c in ['direct','semaphore'] or c.startswith('rate-') else '#76d9bc' for c in cases]
 def rows(phase):return [next(r for r in d['rows'] if r['case']==c and r['phase']==phase and r['service']=='all' and r['priority']=='critical') for c in cases]
 fig,axes=plt.subplots(1,2,figsize=(16,10))
 for i,(phase,title) in enumerate([('healthy','Healthy · 120 total requests/sec'),('sustained','Overload · 1,800 total requests/sec, 10 ms SQL delay')]):
  rs=rows(phase);vs=[r['timely_rps'] for r in rs];axes[i].barh(range(len(cases)),vs,color=colors,xerr=[[r['timely_rps']-r['timely_min'] for r in rs],[r['timely_max']-r['timely_rps'] for r in rs]],error_kw={'ecolor':'#dae8df','capsize':3});axes[i].invert_yaxis();axes[i].set_yticks(range(len(cases)),[LABELS[c] for c in cases] if i==0 else []);axes[i].set_title(title,fontsize=11);axes[i].set_xlabel('Critical successes within 100 ms from schedule / sec');axes[i].grid(axis='x',alpha=.12);axes[i].set_axisbelow(True);axes[i].spines[['top','right']].set_visible(False)
 fig.suptitle('Useful work under healthy traffic and overload',x=.025,ha='left',fontsize=17,y=.97);fig.text(.025,.025,'Three repeats; medians with min/max whiskers, not confidence intervals. Same SQL pools, workload and deadlines.\nClassless semaphore/fixed-unreserved have ceiling 4. Other Gatewise cases reserve 1 of 4 for critical. Rate caps are per service.\nDirect/rate have no HTTP concurrency ceiling. Proxy adds a process/hop. See refusal/error costs and both priorities in the table.',color='#a9bfb0');fig.tight_layout(rect=(0,.12,1,.93));fig.savefig(ROOT/'public/images/comparison-useful.png',dpi=150);plt.close(fig)
 fig,axes=plt.subplots(1,3,figsize=(17,10));rs=rows('sustained')
 for i,(key,label) in enumerate([('p95_ms','Successful critical p95 · ms'),('rejected_percent','Critical refused · % offered'),('server_error_percent','Critical server errors · % offered')]):
  axes[i].barh(range(len(cases)),[r[key] or 0 for r in rs],color=colors);axes[i].invert_yaxis();axes[i].set_yticks(range(len(cases)),[LABELS[c] for c in cases] if i==0 else []);axes[i].set_xlabel(label);axes[i].grid(axis='x',alpha=.12);axes[i].set_axisbelow(True);axes[i].spines[['top','right']].set_visible(False)
 fig.suptitle('Latency, refusals and errors during overload',x=.025,ha='left',fontsize=17,y=.97);fig.text(.025,.025,'1,800 total requests/sec, 10 ms SQL delay. Successful p95 is the median of run-level p95s; percentages pool counts.\nRefused work includes explicit 503 capacity refusals and 429 token-bucket refusals. Refusals are not successful work.\nServer errors include SQL deadlines/failures. Background outcomes, tight client deadlines and pool waiting remain in the full table/report.',color='#a9bfb0');fig.tight_layout(rect=(0,.12,1,.93));fig.savefig(ROOT/'public/images/comparison-costs.png',dpi=150);plt.close(fig)
