 fig,ax=plt.subplots(figsize=(15,10));critical=[next(r for r in d['rows'] if r['case']==c and r['phase']=='background-flood' and r['service']=='all' and r['priority']=='critical') for c in cases];background=[next(r for r in d['rows'] if r['case']==c and r['phase']=='background-flood' and r['service']=='all' and r['priority']=='background') for c in cases]
